<?php require_once '../config/app.php';require_once '../includes/security.php';start_secure_session();require_user();$pdo=db();$st=$pdo->prepare("SELECT a.*,j.job_title,j.organization FROM applications a JOIN jobs j ON j.id=a.job_id WHERE a.user_id=? ORDER BY a.created_at DESC");$st->execute([$_SESSION['user_id']]);$rows=$st->fetchAll();$page_title='My Applications';$asset_prefix='../';$home_link='../index.php';require '../includes/header.php';?><h1>My Applications</h1><div class="card table-wrap"><table><tr><th>Job</th><th>Organization</th><th>Status</th><th>Date</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['job_title'])?></td><td><?=e($r['organization'])?></td><td><?=e($r['application_status'])?></td><td><?=e($r['applied_at'])?></td></tr><?php endforeach;?></table><?php if(!$rows):?><div class="empty">No applications recorded yet.</div><?php endif;?></div><?php require '../includes/footer.php';?>